function parseAttrs(s: string): Record<string, string> {
  const attrs: Record<string, string> = {};
  const re = /(\w[\w-]*)="([^"]*)"/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    if (m[1] !== 'fill' && m[1] !== 'class') attrs[m[1]] = m[2];
  }
  return attrs;
}

export default function IhIcon({
  name,
  className = 'w-6 h-6',
  ...props
}: { name: IhIconName; className?: string } & SVGProps<SVGSVGElement>) {
  const { vb, paths, rects, polys } = icons[name];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={vb}
      fill="currentColor"
      className={className}
      aria-hidden="true"
      {...props}
    >
      {paths.map((d, i) => <path key={'p'+i} d={d} fillRule="evenodd" />)}
      {rects?.map((r, i) => {
        const a = parseAttrs(r.replace('RECT:', ''));
        return <rect key={'r'+i} {...a} />;
      })}
      {polys?.map((p, i) => {
        const a = parseAttrs(p.replace('POLY:', ''));
        return <polygon key={'pg'+i} {...a} />;
      })}
    </svg>
  );
}
